 function tip(n){const c=record(n.id),ss=objectSources(n),edges=graph().edges.filter(e=>e.from===n.id||e.to===n.id),gap=findings().find(f=>f.objectId===n.id),brief=s=>String(s||'').slice(0,210);return '<div class="tip-top">Chapter 6 / '+esc(bridge.state.tab)+' · '+esc(c?.ref||n.ref||n.layer)+'</div><h3>'+esc(n.title)+'</h3><p>'+esc(brief(n.description))+'</p><p>'+esc(brief(edges.slice(0,2).map(e=>e.label+' '+label(e.from===n.id?e.to:e.from)).join(' · ')))+'</p><p>'+esc(ss.applications.map(a=>a.ref).join(' · '))+' '+esc(ss.drivers.map(d=>d.id).join(' · '))+'</p><small>'+esc(gap?.detail||contextText())+'</small><small>Select to pin its context in the bottom panel and review a ghost suggestion.</small>'}
