 function goMilestone(id){close(true);if(id==='intake')return intake();if(id==='handoff')return handoff();if(id==='validate')return bridge.setTab('validate');if(id==='simulate')return startSimulation();workStage=id==='needs'?'needs':id==='resilience'?'dependencies':'capabilities';bridge.setTab('work')}
 async function download(md){try{const response=await projectFetch('/api/export?chapter=6&format='+(md?'md':'json'),{credentials:'same-origin'});if(!response.ok)throw Error('The export could not be prepared. Reopen the project and try again.');let content;if(md){content=await response.text();if(bridge.state.note)content+='\n## Architect’s note (this browser)\n\n'+bridge.state.note+'\n';}else{const data=await response.json();data.browserExploration={architectNote:bridge.state.note,chapter:6,visibleLayers:bridge.state.visible,technologyPerspective:view};content=JSON.stringify(data,null,2)}const url=URL.createObjectURL(new Blob([content],{type:md?'text/markdown':'application/json'})),a=document.createElement('a');a.href=url;a.download=projectFileName(md?'AIW_Bank_Payment_Logical_Technology.md':'AIW_Bank_Payment_Project.json');a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);bridge.toast('Export prepared with technology references, support mappings, simulation assumptions, and open findings.')}catch(e){notifyError(e.message)}}

 function startSimulation(id){close(true);pause();proposal=null;const c=record(id)||record(selected().id)||records().find(c=>c.category==='transactional')||records()[0];simulation=simulateTechnology(project(),{capabilityId:c.id,mode:'capability',durationMinutes:20});simulationStep=0;simulationDirty=false;measurementDirty=false;pendingScenario=null;pendingMeasurements=null;visited=new Set([0]);view='all';bridge.state.visible=['physical','technology'];bridge.state.selected=c.id;bridge.state.focus=false;bridge.setTab('model');document.querySelector('#flow-panel')?.scrollIntoView({block:'nearest'});}
 function failureSurface(){if(!simulation)return '<div class="t-failure-invite"><div><span class="eyebrow">Failure lab / Illustrative what-if</span><p>Lose a capability or a shared failure domain. Trace affected applications and review the quality consequences.</p></div>'+B('simulate','Explore a failure','gold')+'</div>';
  const settings=pendingScenario||simulation,current=record(simulation.capabilityId),titles=['Failure','Propagation','Quality targets','Recovery'],unmet=simulation.assessments.filter(a=>a.result==='unmet-assumption').length;
  return '<section class="t-failure-lab" aria-label="Technology failure simulation"><header><div><span class="eyebrow">Failure lab / Simulation</span><h3>'+esc(current?.title)+' · '+(simulation.mode==='domain'?'domain loss':'capability outage')+'</h3></div>'+B('clear-simulation','Close simulation')+'</header><form id="t-simulation-form"><div class="t-sim-inputs">'+select('Failed capability','capabilityId',records().map(c=>[c.id,c.ref+' · '+c.title]),settings.capabilityId)+select('Failure scope','mode',[['capability','Entire capability unavailable'],['domain','Primary failure domain lost']],settings.mode)+field('Outage assumption (minutes)','durationMinutes',settings.durationMinutes,false,'type="number" min="0.1" step="any" required')+'</div>'+B('apply-simulation','Apply scenario assumptions')+'</form><nav class="t-sim-stages" aria-label="Failure exploration steps">'+titles.map((title,i)=>B('simulation-step',String(i+1).padStart(2,'0')+' '+title,simulationStep===i?'active':'',{'data-t-step':i,'aria-pressed':simulationStep===i})).join('')+'</nav><div class="t-sim-results" role="status">'+(simulationStep===0?'<h3>What has failed?</h3><p>'+(simulation.mode==='domain'?'Capabilities in <b>'+esc(simulation.failedDomain)+'</b> share this failure scope. Independent alternates remain declared assumptions.':'The entire capability is unavailable, including its internal copies. A separate domain-loss scenario explores declared alternates.')+'</p>':simulationStep===1?'<h3>'+simulation.applications.length+' application'+(simulation.applications.length===1?'':'s')+' affected</h3><p>All mapped capabilities are required for an application need. Critical prerequisites propagate failure; data movement and recovery links do not. Alternate support is declared within a capability’s continuity arrangement.</p><div class="t-impact-apps">'+simulation.applications.map(a=>'<button class="t-impact '+a.state+'" data-select="'+a.id+'"><b>'+a.ref+' · '+esc(a.title)+'</b><span>'+a.state+' · '+a.needs.map(n=>n.id).join(', ')+'</span></button>').join('')+'</div>':simulationStep===2?'<h3>'+unmet+' target'+(unmet===1?'':'s')+' unmet under the stated assumptions</h3><p>These are hypothetical outcomes, not measured results. Empty values remain unassessed. Review whether the failure matches each quality scenario’s conditions.</p>':'<h3>What would be needed to resume?</h3><p>'+esc(current?.recoveryPlan||'A restoration and reconciliation plan has not been defined.')+'</p><p>Owner: '+esc(current?.recoveryOwner||'Unassigned')+' · Recovery time: '+esc(current?.recoveryMinutes===''?'Unspecified':current?.recoveryMinutes+' min')+'</p><p>'+model().dependencies.filter(d=>d.from===current?.id&&d.type==='resilience').map(d=>esc(label(d.to))+': '+esc(d.policy)).join('<br>')+'</p>'+B('edit-continuity','Review recovery arrangement','',{'data-t-id':current?.id}))+'</div>'+(simulationStep===2?'<form id="t-measurements-form"><div class="t-target-table">'+simulation.assessments.map(saved=>{const a={...saved,...pendingMeasurements?.find(m=>m.driverId===saved.driverId)};return '<details class="t-assessment"'+(a.value!==''?' open':'')+'><summary><span>'+esc(a.driverId+' · '+a.title)+'</span>'+badge(a.result==='unmet-assumption'?'Unmet · assumed':a.result==='met-assumption'?'Met · assumed':'Not assessed',a.result!=='met-assumption')+'</summary><section class="t-target-row"><div><a href="/?chapter=2&driver='+a.driverId+'">'+a.driverId+' · '+esc(a.title)+'</a><p>'+esc(a.metric)+'</p><small>'+esc(a.target)+' · '+(a.targetConfirmed?'Confirmed target':'Target assumption')+'</small>'+badge(a.result==='unmet-assumption'?'Unmet · assumed outcome':a.result==='met-assumption'?'Met · assumed outcome':'Not assessed',a.result!=='met-assumption')+'</div><div>'+field('Assumed value for '+a.driverId+' ('+a.unit+')','value:'+a.driverId,a.value,false,'type="number" min="0" step="any"')+field('Basis for '+a.driverId,'basis:'+a.driverId,a.basis,true)+'</div></section></details>';}).join('')+'</div>'+B('apply-measurements','Apply quality assumptions')+'</form>':'')+'<div class="t-sim-footer"><span>Illustrative simulation · '+visited.size+' / 4 steps explored</span><div>'+B('restart-simulation','Restart')+B('step-simulation','Step','',simulationStep===3?{disabled:'disabled'}:{})+B(playing?'pause-simulation':'play-simulation',playing?'Pause':'Play')+'</div></div><div class="l-scenario-review"><span>Record the assumptions and effects for this model revision.</span>'+B('record-simulation','Record failure review','',visited.size===4?{}:{disabled:'disabled'})+'</div></section>';
 }
 function simulationFrame(index){if(!simulation)return;simulationStep=Math.max(0,Math.min(3,index));visited.add(simulationStep);refresh()}
 function playSimulation(){if(!simulation)return startSimulation();if(simulationStep===3){simulationStep=-1;visited.clear()}playing=true;const advance=()=>{simulationFrame(simulationStep+1);if(simulationStep<2)timer=setTimeout(advance,1800);else{playing=false;refresh()}};advance()}
 function applySimulation(){const form=document.querySelector('#t-simulation-form');try{simulation=simulateTechnology(project(),Object.fromEntries(new FormData(form)));pause();simulationDirty=false;measurementDirty=false;pendingScenario=null;pendingMeasurements=null;visited=new Set([0]);simulationStep=0;refresh();bridge.toast('Scenario assumptions applied. Walk through the updated effects.')}catch(e){notifyError(e.message)}}
 function applyMeasurements(){const fd=new FormData(document.querySelector('#t-measurements-form'));try{const measurements=simulation.assessments.map(a=>({driverId:a.driverId,value:String(fd.get('value:'+a.driverId)||''),basis:String(fd.get('basis:'+a.driverId)||'')}));if(measurements.some(m=>m.value!==''&&!m.basis.trim()))throw Error('Explain the basis for each assumed quality value.');simulation=simulateTechnology(project(),{...simulation,measurements});measurementDirty=false;pendingMeasurements=null;visited.delete(3);refresh();bridge.toast('Quality assumptions updated. Review recovery before recording.')}catch(e){notifyError(e.message)}}
 async function action(action,b){
  const moves=['simulation-step','step-simulation','restart-simulation','play-simulation','record-simulation'];
  if(moves.includes(action)&&(simulationDirty||measurementDirty)){pause();notifyError(simulationDirty?'Apply the changed scenario assumptions before continuing.':'Apply the edited quality assumptions before continuing.');return;}
  switch(action){
   case 'new':editCapability();break;case 'edit':editCapability(b.dataset.tId||selected().id);break;case 'edit-continuity':editCapability(b.dataset.tId||selected().id,2);break;
   case 'needs':editNeeds(b.dataset.tId);break;case 'connect':editDependency(null,selected().id);break;case 'dependency':editDependency(b.dataset.tId);break;case 'boundary':editBoundary(b.dataset.tId);break;
   case 'remove-dependency':dialog('Remove '+b.dataset.tId+'?','<p>The capability records remain. Removing a relationship may leave an unsupported or unclear recovery path.</p><form id="t-remove-form">'+actions('Remove dependency')+'</form>','remove',{id:b.dataset.tId});break;
   case 'work-stage':workStage=b.dataset.tStage;refresh();break;case 'lens':lensTab=b.dataset.tLens;document.querySelector('#inspector').innerHTML=inspector();break;
   case 'view':view=b.dataset.tView;bridge.state.visible={support:['physical','technology'],data:['physical','technology','data','interface'],trust:['physical','technology','security'],resilience:['physical','technology','deployment'],all:['physical','technology','data','security','deployment']}[view];bridge.state.focus=false;bridge.state.zoom=1;bridge.state.pan={x:0,y:0};bridge.persist();refresh();break;
   case 'inspect':close(true);bridge.state.tab='model';lensTab='context';bridge.selectNode(b.dataset.tId);refresh();break;
   case 'need-context':{const n=model().needs.find(n=>n.id===b.dataset.tId);if(!n)break;const ms=model().mappings.filter(m=>m.needId===n.id);dialog(n.id+' · '+categoryName(n.category),'<p>'+esc(n.description)+'</p>'+badge(n.confirmed&&!needChanged(project(),n)?'Need reviewed':'Need requires review',!n.confirmed)+'<div class="l-source-links">'+ms.map(m=>B('inspect',record(m.capabilityId)?.ref+' · '+label(m.capabilityId),'',{'data-t-id':m.capabilityId})).join('')+'</div>'+B('needs','Edit application needs','',{'data-t-id':n.applicationId})+(!ms.length?B('preview','Review missing capability','gold',{'data-t-key':'missing','data-t-id':n.applicationId,'data-t-need':n.id}):''),'need-context');break}
   case 'preview':preview(b.dataset.tKey,b.dataset.tId||selected().id,b.dataset.tNeed);break;case 'edit-ghost':editGhost();break;
   case 'preview-edits':{const raw=readCapability(document.querySelector('#t-capability-form'));if(!raw.title.trim())return notifyError('Name the proposed capability.');proposal={...proposal,record:{...proposal.record,...raw},mappings:raw.mappings};dirty=false;close(true);refresh();bridge.toast('Edited ghost preview. The saved project is unchanged.');break}
   case 'dismiss':bridge.state.selected=proposal?.record.id||proposal?.objectId||'postgres';proposal=null;refresh();bridge.toast('Proposal dismissed. The saved technology model is unchanged.');break;
   case 'sol':assistant('sol');break;case 'mind':assistant('mind');break;case 'close':close();break;case 'keep':document.querySelector('.t-discard').hidden=true;break;case 'discard':close(true);break;case 'step':step(Number(b.dataset.tStep));break;
   case 'intake':intake();break;case 'milestone':goMilestone(b.dataset.tId);break;case 'validate':close(true);bridge.setTab('validate');break;case 'run-checks':bridge.state.tab='validate';await send('review',{},'Technology checks recorded for this model.');break;
   case 'filter':filter=b.dataset.tFilter;refresh();break;case 'fix':fix(b.dataset.tId);break;case 'fix-first':fix(findings().find(f=>f.level==='error')?.id||findings()[0]?.id);break;
   case 'handoff':handoff();break;case 'chapter7':chapter7();break;case 'export-json':download(false);break;case 'export-md':download(true);break;case 'back-model':bridge.setTab('model');document.querySelector('#canvas')?.scrollIntoView({block:'start'});break;
   case 'simulate':startSimulation(b.dataset.tId);break;case 'clear-simulation':pause();simulation=null;visited.clear();refresh();break;case 'apply-simulation':applySimulation();break;case 'apply-measurements':applyMeasurements();break;case 'simulation-step':pause();simulationFrame(Number(b.dataset.tStep));break;case 'restart-simulation':pause();visited.clear();simulationFrame(0);break;case 'step-simulation':pause();simulationFrame(simulationStep+1);break;case 'play-simulation':playSimulation();break;case 'pause-simulation':pause();refresh();break;
   case 'record-simulation':pause();await send('simulation',{capabilityId:simulation.capabilityId,mode:simulation.mode,durationMinutes:simulation.durationMinutes,measurements:simulation.assessments.map(a=>({driverId:a.driverId,value:a.value,basis:a.basis})),visited:[...visited],reviewed:true},'Failure review saved with its explicit assumptions.');break;
   case 'reload':try{await store.load();notifyError('Latest project loaded. Your unsaved fields are preserved; review them before saving.')}catch(e){notifyError(e.message)}break;
  }
 }
 document.addEventListener('click',e=>{const b=e.target.closest('[data-t-action]');if(!b||b.disabled||busy)return;e.preventDefault();action(b.dataset.tAction,b)});
 document.addEventListener('input',e=>{if(e.target.closest('#t-simulation-form')){simulationDirty=true;pendingScenario=Object.fromEntries(new FormData(e.target.form));pause();}if(e.target.closest('#t-measurements-form')){measurementDirty=true;const fd=new FormData(e.target.form);pendingMeasurements=simulation.assessments.map(a=>({driverId:a.driverId,value:String(fd.get('value:'+a.driverId)||''),basis:String(fd.get('basis:'+a.driverId)||'')}));pause();}if(!e.target.closest('.t-dialog form'))return;dirty=true;const state=e.target.form.elements.status;if(e.target.name!=='status'&&state?.value==='reviewed')state.value='candidate';if(['recoveryMinutes','lossMinutes'].includes(e.target.name)&&e.target.form.elements.targetsConfirmed)e.target.form.elements.targetsConfirmed.checked=false});
 document.addEventListener('change',e=>{if(e.target.closest('#t-simulation-form')){simulationDirty=true;pendingScenario=Object.fromEntries(new FormData(e.target.form));pause();}if(!e.target.closest('.t-dialog form'))return;dirty=true;if(e.target.name==='categories'){const el=document.querySelector('[data-t-category="'+e.target.value+'"]');if(el)el.hidden=!e.target.checked}if(e.target.name==='needIds'){const el=document.querySelector('[data-t-scope="'+e.target.value+'"]');if(el)el.hidden=!e.target.checked}});
 document.addEventListener('invalid',e=>{const p=e.target.closest('[data-t-panel]');if(p)step(Number(p.dataset.tPanel))},true);
 document.addEventListener('submit',async e=>{if(!e.target.closest('.t-dialog'))return;e.preventDefault();const f=e.target,fd=new FormData(f);
  if(f.id==='t-needs-form')await send('needs',{applicationId:dialogContext.id,boundaryId:fd.get('boundaryId'),confirmed:fd.has('confirmed'),needs:fd.getAll('categories').map(category=>({category,description:fd.get('need:'+category),criticality:fd.get('criticality:'+category)}))});
  else if(f.id==='t-capability-form'){const raw=readCapability(f);if(dialogContext.type==='proposal')await send('proposal',{key:proposal.key,objectId:proposal.objectId,needId:proposal.needId,record:raw,mappings:raw.mappings,reviewed:raw.reviewed},'Reviewed technology proposal saved.');else await send('capability',{...raw,id:dialogContext.id});}
  else if(f.id==='t-dependency-form')await send('dependency',{...Object.fromEntries(fd),critical:fd.has('critical'),id:dialogContext.id});
  else if(f.id==='t-boundary-form')await send('boundary',{...Object.fromEntries(fd),id:dialogContext.id});
  else if(f.id==='t-remove-form')await send('remove-dependency',{id:dialogContext.id},'Dependency removed. The capabilities remain in the model.');
  else if(f.id==='t-intake-form')await send('intake',{},'Application inputs reviewed.');
  else if(f.id==='t-handoff-form')await send('handoff',{acknowledge:fd.has('acknowledge')},'Logical technology carried into Chapter 7.',chapter7);
 });
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
 return {editImpact(c){editCapability(c.payload.id,0,{...record(c.payload.id),...c.payload})},bind(b){bridge=b},graph,work,validation,output,inspector,controls,assistance,tip,assistant,failureSurface,pause,preview,accept:editGhost,milestones,next(){const m=milestones().find(m=>!m.done);if(m)goMilestone(m.id);else chapter7()},get busy(){return busy},get groups(){return project().logical.groups},get proposal(){return proposal}};
